using System.Windows;using System.Windows.Controls;
namespace MizanDesktop.Services;
public static class DialogService{public static string? Prompt(string title,string label,bool password=false){var w=new Window{Title=title,Width=420,Height=190,WindowStartupLocation=WindowStartupLocation.CenterOwner,ResizeMode=ResizeMode.NoResize,FlowDirection=FlowDirection.RightToLeft};var p=new StackPanel{Margin=new Thickness(20)};p.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,0,0,8)});Control box=password?new PasswordBox():new TextBox();box.Height=30;p.Children.Add(box);var b=new Button{Content="موافق",Margin=new Thickness(0,12,0,0),Width=90,HorizontalAlignment=HorizontalAlignment.Left};b.Click+=(s,e)=>{w.DialogResult=true;w.Close();};p.Children.Add(b);w.Content=p;if(w.ShowDialog()!=true)return null;return box is PasswordBox pb?pb.Password:((TextBox)box).Text;}}
